use crate::config::CssConfig;
use crate::pre_subset::name_table::NameTableSets;
use chrono::Utc;

pub fn create_header_comment(
    css: &CssConfig,
    name_table: &NameTableSets,
    version: &str,
) -> String {
    let mut comment = String::new();

    if css.comment_base {
        let utc = Utc::now();
        comment.push_str(&format!(
            "Generated By cn-font-split@{} https://www.npmjs.com/package/cn-font-split\nCreateTime: {};\n",
            version,
            utc.to_rfc3339()
        ));
    }

    if css.comment_name_table {
        let name_table_comment = name_table
            .table
            .iter()
            .map(|x| {
                format!("{} {} {} {}", x.platform, x.language, x.name, x.value)
            })
            .collect::<Vec<String>>()
            .join("\n");
        comment.push_str(&name_table_comment);
    }

    if comment.is_empty() {
        return String::new();
    }
    format!("/* {}\n */\n\n", comment.trim())
}
